document.addEventListener('DOMContentLoaded',function(){'use strict';const titles=document.querySelectorAll('.oc-accordion .item-title');titles.forEach(function(title){title.addEventListener('click',function(event){event.preventDefault();this.classList.toggle('active');const content=this.nextElementSibling;if(content&&content.classList.contains('item-content')){slideToggle(content)}})})})